function UIActionDreamlandBattleEndDialog:FillSelf()
    local vo = DreamlandUtils.GetDreamlandQuestVo(self._questId)
    if not vo then
        return
    end

    CfUtils.FillText(self.TxtCompletedState, vo.levelName)
    --local allCount = DreamlandUtils.GetAllCollectionCount(self._questId)
    local allCount = DreamlandUtils.GetAllPiecesNumByQuestId(self._questId)
    CfUtils.FillText(self.TxtNum, table.count(self._collectionIds).."/"..allCount)

    self.LoopListGoods:InitGridView(table.count(self._rewards), Bind(self, self.OnRefreshPlaceIndex))
end



function UIActionDreamlandBattleEndDialog:OnRefreshPlaceIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local data = self._rewards[index + 1]
    local go = cell.gameObject

    CfUtils.RefeshGoodGo2(go.transform:Find("GoodNode"), data.goodsId, data.goodsNum, nil, nil, function()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
        GameUtils.ShowCommonTipsBoard(go, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end)

    return cell
end




