function UIActionDreamlandBattleEndDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._questId = checkNumber(argument.id)  
        self._rewards_dojo = checkTable(argument.rewards)  -- 后端数据, 启用, 下面自己装填新的...
        self._collectionIds = checkTable(argument.collectionIds)
        
        
        self:PrepareRewardsFromDojo( self._rewards_dojo )
        --self:PrepareRewardsFromVO() -- 装填 self._rewards
        -- 奖励已经在接口处领取了:

        if table.count(self._rewards) > 0 then
            CfUtils.FillText( self.TxtTitle.gameObject, localize("获得奖励") )
        else 
            CfUtils.FillText( self.TxtTitle.gameObject, "" )
        end 

        self.ContainerCanvasGroup = KTool.GetComponent(self.Container.gameObject, typeof(CanvasGroup))

        if self.co ~= nil then  
            cs_coroutine.stop(self.co)
        end 
        self.co = cs_coroutine.start(function()

            --KTool.SetActive( self.Container.gameObject, false )

            self.ContainerCanvasGroup.alpha = 0.0
            
            -- 黑幕淡入:
            local speed = 0.5
            local t = 0.0
            while t<1.0 do 
                self.tmpColor.a = t
                self.fullBlack.color = self.tmpColor
                t = t + speed * Time.deltaTime
                coroutine.yield(Yielders.EndOfFrame)
            end

            cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 1.0 ))


            --KTool.SetActive( self.Container.gameObject, true )

            self:FillSelf()

            t = 0.0 
            local speed2 = 0.8
            while t<1.0 do
                self.ContainerCanvasGroup.alpha = t
                t = t + speed2 * Time.deltaTime
                coroutine.yield(Yielders.EndOfFrame)
            end
            self.ContainerCanvasGroup.alpha = 1.0

            
        end)


        --self:FillSelf()
    end))
    return coWait
end

function UIActionDreamlandBattleEndDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()


        DreamSpaceSounds.Stop( DreamSpaceSounds.music.dream )

        if self.co ~= nil then  
            cs_coroutine.stop(self.co)
        end 
        self.co = nil
        ---
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end



-- 从配表中手动生成 奖励信息:
-- todo: 不安全, 可能和后端数据不匹配, 改用 PrepareRewardsFromDojo()
function UIActionDreamlandBattleEndDialog:PrepareRewardsFromVO()

    self._rewards = {}
    local vo = DreamlandUtils.GetDreamlandQuestRewardVo(DreamSpaceStates.questId )
    if isNull(vo) then 
        printError("koko 配表读取为 空")
        return
    end

    local isNeedMajorReward = (DreamSpaceStates.isMajorRewardDrawed == false)
    local isNeedPieceReward = (DreamSpaceStates.isAllPiecesCollectedAlready == false and DreamSpaceStates.isAllPiecesCollectedThisTime == true )
    -- local isNeedMajorReward = true
    -- local isNeedPieceReward = true

    local tmpDic = {} -- 本地先把 两份奖励 合并为一份奖励;
    if isNeedMajorReward == true then 
        print("koko -- 可拿到 主奖励")
        local majorRewards  = parse_rewards(vo.fristRewards,     vo.fristRewardsNum)
        for _,r in pairs(majorRewards) do 

            if tmpDic[r.goodsId] == nil then 
                tmpDic[r.goodsId] = r.goodsNum
            else 
                if type(tmpDic[r.goodsId]) ~= "number" then 
                    printError("koko 奖励数据异常")
                    tmpDic[r.goodsId] = r.goodsNum -- 补个假的
                else 
                    tmpDic[r.goodsId] = tmpDic[r.goodsId] + r.goodsNum
                end
            end 
        end 
    end

    if isNeedPieceReward == true then 
        print("koko -- 可拿到 碎片奖励")
        local piecesRewards = parse_rewards(vo.collectionReward, vo.collectionRewardNum)
        for _,r in pairs(piecesRewards) do 

            if tmpDic[r.goodsId] == nil then 
                tmpDic[r.goodsId] = r.goodsNum
            else 
                if type(tmpDic[r.goodsId]) ~= "number" then 
                    printError("koko 奖励数据异常")
                    tmpDic[r.goodsId] = r.goodsNum -- 补个假的
                else 
                    tmpDic[r.goodsId] = tmpDic[r.goodsId] + r.goodsNum
                end
            end 
        end 
    end 

    for id,num in pairs(tmpDic) do 
        table.insert(self._rewards, {
            goodsId = id,
            goodsNum = num,     -- CfUtils.RefeshGoodGo2() 需要 goodsNum 字段
            num = num           -- GoodsUtils.DrawRewards() 需要 num 字段
        })
    end 
end 



function UIActionDreamlandBattleEndDialog:PrepareRewardsFromDojo( rawRewards_ )

    local isNeedMajorReward = (DreamSpaceStates.isMajorRewardDrawed == false)
    local isNeedPieceReward = (DreamSpaceStates.isAllPiecesCollectedAlready == false and DreamSpaceStates.isAllPiecesCollectedThisTime == true )

    if isNeedMajorReward or isNeedPieceReward then 
        if table.count(rawRewards_) == 0 then 
            printError("koko - 本该有奖励, 但后端没返回; 需要通关奖励(?): " .. tostring(isNeedMajorReward) .. "; 需要碎片奖励(?): " .. tostring(isNeedPieceReward) )
            return
        end
    end

    self._rewards = {}
    local tmpDic = {} -- 本地先把 两份奖励 合并为一份奖励;

    print("koko - 后端奖励:")
    for i=1, table.count(rawRewards_) do 
        local r = rawRewards_[i]
        print( tostring(i) .. " -- num: " .. tostring(r.num) .. ", goodsId: " .. tostring(r.goodsId)  )

        if tmpDic[r.goodsId] == nil then 
            tmpDic[r.goodsId] = r.num
        else 
            if type(tmpDic[r.goodsId]) ~= "number" then 
                printError("koko 奖励数据异常")
                tmpDic[r.goodsId] = r.num -- 补个假的
            else 
                tmpDic[r.goodsId] = tmpDic[r.goodsId] + r.num
            end
        end 
    end 

    for id,num in pairs(tmpDic) do 
        --print("-- id: " .. tostring(id) .. ", num = " .. tostring(num))
        table.insert(self._rewards, {
            goodsId = id,
            goodsNum = num,     -- CfUtils.RefeshGoodGo2() 需要 goodsNum 字段
            num = num           -- GoodsUtils.DrawRewards() 需要 num 字段
        })
    end 

    print("_rewards num: " .. tostring(table.count(self._rewards)) )
    for i=1, table.count(self._rewards) do 
        local r = self._rewards[i]
        print( "_rewards " .. tostring(i) .. ": goodsId: " .. tostring(r.goodsId) .. ", goodsNum: " .. tostring(r.goodsNum) .. ", num: " .. tostring(r.num) )
    end

end




return UIActionDreamlandBattleEndDialog
